    centers = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color not in (0, 3) and 0 < r < h-1 and 0 < c < w-1:
                if all(grid[rr][cc] == 3 for rr,cc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1))):
                    centers.append((r,c,color))
    # Extend each center's color along its row and column, through grid edges.
    for r,c,color in centers:
        for rr in range(h):
            if grid[rr][c] == 0 and not any((rr,c)==(r0,c0) for r0,c0,_ in centers):
